def extract_params(path_params: dict, query_params: dict, body, spec: dict) -> tuple:
    sources = {"path": path_params or {}, "query": query_params or {}, "body": body or {}}
    errors = []
    parsed = {"path": {}, "query": {}, "body": {}}
    for src_name in ("path", "query", "body"):
        rules = spec.get(src_name, {})
        src_data = sources[src_name]
        for field, (typ, required, default) in rules.items():
            if field not in src_data:
                if required:
                    errors.append({"loc": [src_name, field], "msg": "Field required", "type": "missing"})
                else:
                    parsed[src_name][field] = default
                continue
            raw_val = src_data[field]
            try:
                if typ is bool and isinstance(raw_val, str):
                    low = raw_val.lower()
                    if low in ("true", "1"):
                        parsed[src_name][field] = True
                    elif low in ("false", "0"):
                        parsed[src_name][field] = False
                    else:
                        raise ValueError("Invalid bool")
                else:
                    parsed[src_name][field] = raw_val if isinstance(raw_val, typ) and typ is not bool else typ(raw_val)
            except (ValueError, TypeError) as exc:
                errors.append({"loc": [src_name, field], "msg": str(exc), "type": "value_error"})
    if errors:
        return (422, {"detail": errors})
    return (200, parsed)

