            return (422, {}, {"detail": "id and name must be non-empty strings"})
        if item_id in self.items:
            return (409, {}, {"detail": "Item already exists"})
        item = {"id": item_id, "name": name}
        self.items[item_id] = item
        return (201, {"Location": f"/items/{item_id}"}, item)

    def get(self, item_id: str) -> tuple:
        if item_id not in self.items:
            return (404, {}, {"detail": "Not found"})
        return (200, {}, self.items[item_id])

    def delete(self, item_id: str) -> tuple:
        if item_id not in self.items:
            return (404, {}, {"detail": "Not found"})
        del self.items[item_id]
        return (204, {}, None)

