from collections import deque

class GuardedPool:
    def __init__(self, max_workers: int, max_queue: int):
        self.max_workers = max_workers
        self.max_queue = max_queue
        self.active = []
        self.queue = deque()
        self.outcomes = {}

    def submit(self, task_id, cost: int, timeout: int):
        item = {"id": task_id, "rem": cost, "timeout": timeout, "elapsed": 0}
        if len(self.active) < self.max_workers:
            self.active.append(item)
        elif len(self.queue) < self.max_queue:
            self.queue.append(item)
        else:
            raise RuntimeError("Queue full")

    def step(self):
        still_active = []
        for item in self.active:
            item["rem"] -= 1
            item["elapsed"] += 1
            if item["rem"] <= 0:
                self.outcomes[item["id"]] = "ok"
            elif item["elapsed"] >= item["timeout"]:
                self.outcomes[item["id"]] = "timeout"
            else:
                still_active.append(item)
        self.active = still_active
        while len(self.active) < self.max_workers and self.queue:
            self.active.append(self.queue.popleft())

