import json

class MiniFlask:
    def __init__(self):
        self.routes = {}
        self.error_handlers = {}

    def route(self, path: str, methods=None):
        def deco(fn):
            self.routes[path] = (set(m.upper() for m in (methods or ["GET"])), fn)
            return fn
        return deco

    def errorhandler(self, code: int):
        def deco(fn):
            self.error_handlers[code] = fn
            return fn
        return deco

    def get_json(self, raw_body: str, silent=False):
        if not raw_body:
            if silent:
                return None
            raise ValueError("Empty body")
        try:
            return json.loads(raw_body)
        except (ValueError, TypeError):
            if silent:
                return None
            raise

    def _err(self, code: int, default_body: dict, headers=None):
        hdr = dict(headers or {})
        if code in self.error_handlers:
            return (code, hdr, self.error_handlers[code](code))
        return (code, hdr, default_body)

    def handle(self, method: str, path: str, raw_body: str = ""):
        if path not in self.routes:
            return self._err(404, {"error": "Not Found"})
        methods, fn = self.routes[path]
        if method.upper() not in methods:
            allow = ", ".join(sorted(methods))
            return self._err(405, {"error": "Method Not Allowed"}, {"Allow": allow})
        try:
            return (200, {}, fn(raw_body))
        except Exception:
            return self._err(500, {"error": "Internal Server Error"})

