from contextvars import ContextVar

class LocalProxy:
    def __init__(self, var: ContextVar, name: str = "proxy"):
        object.__setattr__(self, "_var", var)
        object.__setattr__(self, "_name", name)

    def _get_current(self):
        obj = object.__getattribute__(self, "_var").get(None)
        if obj is None:
            raise RuntimeError("Working outside of request context")
        return obj

    def __getattr__(self, item):
        return getattr(self._get_current(), item)

    def __setattr__(self, key, value):
        setattr(self._get_current(), key, value)

    def __getitem__(self, key):
        return self._get_current()[key]

class bind_context:
    def __init__(self, var: ContextVar, value):
        self.var = var
        self.value = value
        self.token = None

    def __enter__(self):
        self.token = self.var.set(self.value)
        return self.value

    def __exit__(self, exc_type, exc, tb):
        self.var.reset(self.token)
        return False

