    def __init__(self, engine, model_name: str, filters=None, excludes=None, order_by=None, start=None, stop=None):
        self.engine = engine
        self.model_name = model_name
        self._filters = dict(filters or {})
        self._excludes = dict(excludes or {})
        self._order_by = tuple(order_by or ())
        self._start = start
        self._stop = stop
        self._result_cache = None

    def _clone(self, **changes):
        return QuerySet(
            self.engine,
            self.model_name,
            filters=changes.get('filters', self._filters),
            excludes=changes.get('excludes', self._excludes),
            order_by=changes.get('order_by', self._order_by),
            start=changes.get('start', self._start),
            stop=changes.get('stop', self._stop),
        )

    def _fetch_all(self):
        if self._result_cache is None:
            self._result_cache = list(
                self.engine.execute(
                    self.model_name,
                    dict(self._filters),
                    dict(self._excludes),
                    self._order_by,
                    self._start,
                    self._stop,
                )
            )
        return self._result_cache

    def filter(self, **kwargs):
        nf = dict(self._filters)
        nf.update(kwargs)
        return self._clone(filters=nf)

    def exclude(self, **kwargs):
        ne = dict(self._excludes)
        ne.update(kwargs)
        return self._clone(excludes=ne)

    def order_by(self, *fields):
        return self._clone(order_by=fields)

    def __getitem__(self, item):
        if isinstance(item, slice):
            base_start = self._start or 0
            new_start = base_start + (item.start or 0)
            new_stop = None if item.stop is None else base_start + item.stop
            if self._stop is not None:
                new_stop = self._stop if new_stop is None else min(self._stop, new_stop)
            return self._clone(start=new_start, stop=new_stop)
        return self._fetch_all()[item]

    def __iter__(self):
        return iter(self._fetch_all())

    def __len__(self):
        return len(self._fetch_all())

