class Q:
    def __init__(self, _op='AND', _children=None, _negated=False, **filters):
        self.op = _op
        self.children = list(_children) if _children is not None else list(filters.items())
        self.negated = _negated

    def __and__(self, other):
        return Q(_op='AND', _children=[self, other])

    def __or__(self, other):
        return Q(_op='OR', _children=[self, other])

    def __invert__(self):
        return Q(_op=self.op, _children=self.children, _negated=not self.negated)

    @staticmethod
    def _match_leaf(row: dict, key: str, expected) -> bool:
        if key.endswith('__gt'):
            return row[key[:-4]] > expected
        if key.endswith('__lt'):
            return row[key[:-4]] < expected
        return row.get(key) == expected

    def matches(self, row: dict) -> bool:
        results = []
        for item in self.children:
            if isinstance(item, Q):
                results.append(item.matches(row))
            else:
                results.append(self._match_leaf(row, item[0], item[1]))
        res = all(results) if self.op == 'AND' else any(results)
        return (not res) if self.negated else res

class F:
    def __init__(self, field: str, delta: int = 0):
        self.field = field
        self.delta = delta

    def __add__(self, val: int):
        return F(self.field, self.delta + val)

    def __sub__(self, val: int):
        return F(self.field, self.delta - val)

    def evaluate(self, row: dict):
        return row[self.field] + self.delta

def atomic_update(rows: list, q: Q, updates: dict) -> int:
    updated = 0
    for row in rows:
        if q.matches(row):
            new_vals = {
                k: (v.evaluate(row) if isinstance(v, F) else v)
                for k, v in updates.items()
            }
            row.update(new_vals)
            updated += 1
    return updated

