class ConcurrentTable:
    def __init__(self, bal):
        self.balances = {1: bal}
        self.interfered = False
    def read_balance(self, aid):
        return self.balances[aid]
    def write_balance(self, aid, val):
        if not self.interfered:
            self.interfered = True
            self.balances[aid] -= 50
        self.balances[aid] = val
    def atomic_add(self, aid, delta):
        if self.balances[aid] + delta < 0:
            return False
        self.balances[aid] += delta
        return True
