import heapq

def plan_migrations(migrations: dict) -> list:
    for node, deps in migrations.items():
        for dep in deps:
            if dep not in migrations:
                raise ValueError(f'Missing dependency: {dep}')
    same_app_referenced = set()
    dependents = {node: [] for node in migrations}
    in_degree = {node: 0 for node in migrations}
    for node, deps in migrations.items():
        for dep in deps:
            if dep[0] == node[0]:
                same_app_referenced.add(dep)
            dependents[dep].append(node)
            in_degree[node] += 1
    leaves_by_app = {}
    for node in migrations:
        if node not in same_app_referenced:
            leaves_by_app.setdefault(node[0], []).append(node)
    for app, leaves in sorted(leaves_by_app.items()):
        if len(leaves) > 1:
            raise ValueError(f'merge required: {app}')
    heap = [n for n, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        cur = heapq.heappop(heap)
        order.append(cur)
        for nxt in dependents[cur]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                heapq.heappush(heap, nxt)
    if len(order) != len(migrations):
        raise ValueError('Cycle detected in migrations')
    return order

