class Repo:
    def __init__(self):
        self.sql_count = 0
        self._items = {1: [{'sku': 'A', 'active': True}, {'sku': 'B', 'active': False}], 2: [{'sku': 'C', 'active': True}]}
    def item_qs(self):
        return ItemQS()
    def orders(self):
        repo = self
        class OrderQS:
            def __init__(self, pf=None):
                self.pf = pf
            def prefetch_related(self, arg):
                return OrderQS(arg)
            def all(self):
                repo.sql_count += 1
                cond = {}
                to_attr = None
                if hasattr(self.pf, 'lookup'):
                    repo.sql_count += 1
                    cond = self.pf.queryset.cond if self.pf.queryset else {}
                    to_attr = self.pf.to_attr
                elif self.pf == 'items':
                    repo.sql_count += 1
                res = []
                for oid in (1, 2):
                    filtered = [it for it in repo._items[oid] if all(it.get(k) == v for k, v in cond.items())]
                    obj = OrderObj(oid, repo, filtered)
                    if to_attr:
                        setattr(obj, to_attr, filtered)
                    res.append(obj)
