def _extract_client_ip(request: dict, trusted_proxies: set) -> str:
    remote = request.get('remote_addr', '')
    xff = request.get('headers', {}).get('X-Forwarded-For', '')
    if remote in trusted_proxies and xff:
        ips = [ip.strip() for ip in xff.split(',') if ip.strip()]
        for ip in reversed(ips):
            if ip not in trusted_proxies:
                return ip
        if ips:
            return ips[0]
    return remote

def _is_host_allowed(host_header: str, allowed_hosts: list) -> bool:
    host = host_header.split(':')[0].lower().strip()
    if not host:
        return False
    for pat in allowed_hosts:
        if pat == '*' or host == pat.lower():
            return True
        if pat.startswith('.') and (host.endswith(pat.lower()) or host == pat[1:].lower()):
            return True
    return False

def handle_http_request(request: dict, settings: dict, middlewares: list, routes: dict) -> dict:
    trusted = set(settings.get('trusted_proxies', []))
    client_ip = _extract_client_ip(request, trusted)
    req = dict(request)
    req['client_ip'] = client_ip
    host = req.get('headers', {}).get('Host', '')
    if not _is_host_allowed(host, settings.get('allowed_hosts', [])):
        return {'status': 400, 'body': 'Invalid Host', 'client_ip': client_ip}
    def base_view(r):
        handler = routes.get(r.get('path'))
        if handler is None:
            return {'status': 404, 'body': 'Not Found'}
        return handler(r)
    app = base_view
    for mw in reversed(middlewares):
        app = mw(app)
    return app(req)

