def dispatch_edge_cases(req: dict, routes: dict, allowed_hosts: list, append_slash: bool, debug: bool) -> dict:
    host = req.get('host', '').split(':')[0].lower().strip()
    if not host or host not in [h.lower() for h in allowed_hosts]:
        return {'status': 400, 'body': 'Bad Request'}
    path = req.get('path', '')
    method = req.get('method', 'GET').upper()
    handler = routes.get(path)
    if handler is None:
        if append_slash and not path.endswith('/') and (path + '/') in routes:
            if method == 'GET':
                return {'status': 301, 'location': path + '/'}
        return {'status': 404, 'body': 'Not Found'}
    try:
        return {'status': 200, 'body': handler(req)}
    except Exception as exc:
        body = f'{type(exc).__name__}: {exc}' if debug else 'Internal Server Error'
        return {'status': 500, 'body': body}

