class ModelAdmin:
    list_display = ()
    list_filter = ()
    search_fields = ()
    actions = {}

    def changelist(self, rows: list, filters: dict = None, query: str = '') -> list:
        flt = filters or {}
        q = query.strip().lower()
        filtered = []
        for row in rows:
            if any(row.get(k) != v for k, v in flt.items() if k in self.list_filter):
                continue
            if q and self.search_fields:
                if not any(q in str(row.get(sf, '')).lower() for sf in self.search_fields):
                    continue
            filtered.append(row)
        table = []
        for row in filtered:
            item = {}
            for col in self.list_display:
                if callable(getattr(self, col, None)):
                    item[col] = getattr(self, col)(row)
                else:
                    item[col] = row.get(col)
            table.append(item)
        return table

    def run_action(self, action_name: str, rows: list, selected_ids: list) -> int:
        if action_name not in self.actions:
            raise KeyError(action_name)
        id_set = set(selected_ids)
        targets = [r for r in rows if r.get('id') in id_set]
        self.actions[action_name](targets)
        return len(targets)

    def save_with_inlines(self, parent: dict, children: list, max_num: int) -> dict:
        if len(children) > max_num:
            raise ValueError(f'Too many inlines: {len(children)} > {max_num}')
        parent['inlines'] = [dict(c) for c in children]
        return parent

