class Signal:
    def __init__(self):
        self._receivers = []

    def connect(self, receiver, sender=None, dispatch_uid=None):
        if dispatch_uid is not None:
            for rec, snd, uid in self._receivers:
                if uid == dispatch_uid and snd == sender:
                    return
        self._receivers.append((receiver, sender, dispatch_uid))

    def disconnect(self, receiver=None, sender=None, dispatch_uid=None) -> bool:
        before = len(self._receivers)
        kept = []
        for rec, snd, uid in self._receivers:
            match_uid = dispatch_uid is not None and uid == dispatch_uid and (sender is None or snd == sender)
            match_rec = dispatch_uid is None and rec == receiver and snd == sender
            if not (match_uid or match_rec):
                kept.append((rec, snd, uid))
        self._receivers = kept
        return len(kept) < before

    def send(self, sender, **named) -> list:
        results = []
        for rec, snd, _ in list(self._receivers):
            if snd is None or snd == sender:
                results.append((rec, rec(sender=sender, **named)))
        return results

