class RobustSignal:
    def __init__(self):
        self._receivers = []

    def connect(self, receiver, sender=None):
        self._receivers.append((receiver, sender))

    def send_robust(self, sender, **named) -> list:
        out = []
        for rec, snd in list(self._receivers):
            if snd is None or snd == sender:
                try:
                    out.append((rec, rec(sender=sender, **named)))
                except Exception as exc:
                    out.append((rec, exc))
        return out

class ModelStore:
    def __init__(self, pre_save: RobustSignal, post_save: RobustSignal):
        self.pre_save = pre_save
        self.post_save = post_save
        self.items = {}

    def save(self, obj: dict):
        self.pre_save.send_robust('Model', instance=obj)
        self.items[obj['id']] = dict(obj)
        self.post_save.send_robust('Model', instance=obj)

    def bulk_create(self, objs: list) -> int:
        for obj in objs:
            self.items[obj['id']] = dict(obj)
        return len(objs)

    def qs_update(self, ids: list, **fields) -> int:
        updated = 0
        for oid in ids:
            if oid in self.items:
                self.items[oid].update(fields)
                updated += 1
        return updated

