                hook = getattr(self, f'validate_{name}', None)
                if callable(hook):
                    val = hook(val)
                attrs[name] = val
            self.validated_data = self.validate(attrs)
            return True
        except ValidationError as exc:
            self.errors['detail'] = str(exc)
            return False

