class OrderSerializer:
    def __init__(self):
        self._next_id = 1

    def create(self, validated_data: dict) -> dict:
        data = dict(validated_data)
        items = [dict(it) for it in data.pop('items', [])]
        order = {'id': self._next_id, **data, 'items': items}
        self._next_id += 1
        return order

    def update(self, instance: dict, validated_data: dict) -> dict:
        data = dict(validated_data)
        if 'items' in data:
            instance['items'] = [dict(it) for it in data.pop('items')]
        for k, v in data.items():
            instance[k] = v
        return instance

    def get_total_amount(self, instance: dict) -> int:
        return sum(it['qty'] * it['price'] for it in instance.get('items', []))

    def to_representation(self, instance: dict) -> dict:
        rep = dict(instance)
        rep['items'] = [dict(it) for it in instance.get('items', [])]
        rep['total_amount'] = self.get_total_amount(instance)
        for opt in ('comment', 'promo_code'):
            if opt in rep and (rep[opt] is None or rep[opt] == ''):
                del rep[opt]
        return rep

