def action(detail: bool = False, methods=None, url_path: str = None):
    allowed = [m.upper() for m in (methods or ['GET'])]
    def decorator(fn):
        fn._action_meta = {
            'detail': detail,
            'methods': allowed,
            'url_path': url_path or fn.__name__,
        }
        return fn
    return decorator

