    http_method_names = ('get', 'patch')
    lookup_field = 'slug'

    def handle(self, method: str, lookup_val: str, store: list, payload: dict = None) -> dict:
        m = method.lower()
        allowed = [x.lower() for x in self.http_method_names]
        if m not in allowed:
            allow_hdr = ', '.join(x.upper() for x in self.http_method_names)
            return {'status': 405, 'headers': {'Allow': allow_hdr}}
        target = None
        for item in store:
            if item.get(self.lookup_field) == lookup_val:
                target = item
                break
        if target is None:
            return {'status': 404, 'body': 'Not Found'}
        if m == 'patch' and payload:
            for k, v in payload.items():
                if k != self.lookup_field:
                    target[k] = v
        return {'status': 200, 'body': dict(target)}

