def apply_filterset(rows: list, params: dict, allowed_order: set) -> list:
    result = []
    ordering = params.get('ordering')
    filters = {k: v for k, v in params.items() if k != 'ordering'}
    for row in rows:
        ok = True
        for key, val in filters.items():
            if key.endswith('__gte'):
                f = key[:-5]
                if row.get(f) < val:
                    ok = False; break
            elif key.endswith('__lte'):
                f = key[:-5]
                if row.get(f) > val:
                    ok = False; break
            elif key.endswith('__in'):
                f = key[:-4]
                if row.get(f) not in val:
                    ok = False; break
            else:
                if row.get(key) != val:
                    ok = False; break
        if ok:
            result.append(row)
    if ordering:
        rev = ordering.startswith('-')
        field = ordering.lstrip('-')
        if field not in allowed_order:
            raise ValueError(f'Ordering by {field} not allowed')
        result.sort(key=lambda r: r[field], reverse=rev)
    return result

def paginate_cursor(rows: list, cursor: int = None, limit: int = 2) -> dict:
    ordered = sorted(rows, key=lambda r: r['id'])
    if cursor is not None:
        ordered = [r for r in ordered if r['id'] > cursor]
    page = ordered[:limit]
    has_more = len(ordered) > limit
    next_c = page[-1]['id'] if (page and has_more) else None
    return {'results': page, 'next_cursor': next_c}

